import{_ as s,o as n,c as e,a2 as l}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"B 站解析与下载","description":"","frontmatter":{},"headers":[],"relativePath":"projects/lotus-plugin/docs/bilibili.md","filePath":"projects/lotus-plugin/docs/bilibili.md"}'),i={name:"projects/lotus-plugin/docs/bilibili.md"};function p(o,a,t,r,c,d){return n(),e("div",null,[...a[0]||(a[0]=[l(`<h1 id="b-站解析与下载" tabindex="-1">B 站解析与下载 <a class="header-anchor" href="#b-站解析与下载" aria-label="Permalink to &quot;B 站解析与下载&quot;">​</a></h1><p>返回：<a href="./../README.html">项目主页</a> / <a href="./README.html">文档目录</a></p><h2 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h2><ul><li>支持 B站长链接、短链接、BV 号、av 号和 QQ 分享卡片。</li><li>视频解析会输出图片卡片，并继续走 BBDown 下载后发送视频文件。</li><li>直播只发送信息卡和独立播放器链接，不做直播下载。</li><li>启动后和每日凌晨会清理临时目录，并移除已过期或已丢失文件的下载缓存。</li><li>标题包含特殊符号时，会优先读取 BBDown 产物和可播放媒体文件，不依赖原始标题精确匹配。</li></ul><h2 id="指令用法" tabindex="-1">指令用法 <a class="header-anchor" href="#指令用法" aria-label="Permalink to &quot;指令用法&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;B站链接或编号&gt;</span></span>
<span class="line"><span>#荷花搜视频 &lt;关键词&gt;</span></span>
<span class="line"><span>#看&lt;序号&gt;</span></span>
<span class="line"><span>#荷花看视频 &lt;BV号&gt;</span></span>
<span class="line"><span>#B站下载 &lt;BV号或链接&gt;</span></span>
<span class="line"><span>#荷花下载 &lt;BV号或链接&gt;</span></span>
<span class="line"><span>#B站登录</span></span>
<span class="line"><span>#BBDown登录</span></span>
<span class="line"><span>#初始化工具环境</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h2 id="变量说明" tabindex="-1">变量说明 <a class="header-anchor" href="#变量说明" aria-label="Permalink to &quot;变量说明&quot;">​</a></h2><ul><li><code>B站链接或编号</code>：必填，支持长链、短链、BV 号、av 号和 QQ 分享卡片。</li><li><code>关键词</code>：必填，视频搜索关键词。</li><li><code>序号</code>：必填，搜索结果序号。</li><li><code>BV号或链接</code>：必填，要播放或下载的视频编号或链接。</li></ul><h2 id="补充说明" tabindex="-1">补充说明 <a class="header-anchor" href="#补充说明" aria-label="Permalink to &quot;补充说明&quot;">​</a></h2><p>解析卡片包含封面、主标题、简介、UP主、视频时长和互动数据。</p><p>B 站下载只走 BBDown。ffmpeg 和 aria2 作为工具链自动准备；ffmpeg 会安装完整构建，包含 <code>ffmpeg</code>、<code>ffplay</code>、<code>ffprobe</code> 和随包文件。启动后和每日凌晨会清理临时目录，并移除已过期或已丢失文件的下载缓存。</p><p>下载会先进入独立临时目录，完成后再按 BBDown 输出和清洗后的标题选择最终文件。标题中带特殊符号时不会用原始标题做唯一精确匹配，会优先读取 BBDown 产物和可播放媒体文件，避免下载成功但找不到成品。</p><p>如果工具压缩包下载损坏、解压后缺少可执行文件，或旧目录里残留了不完整的 shared 包，插件会删除损坏目录并重新下载，用户不需要手动进入 <code>data/tools</code> 清理。</p><p>如果所在网络 IPv6 不可用但 aria2 默认尝试 IPv6，可以在 <code>bilibili.download.extra_args</code> 里给 BBDown/aria2 追加强制 IPv4 相关参数，或临时关闭 <code>bilibili.download.use_aria2</code> 后重试。</p><p>直播只发送信息卡和独立播放器链接，不做直播下载。</p>`,15)])])}const h=s(i,[["render",p]]);export{u as __pageData,h as default};
